import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def lcm_of_range(start, end):
    # Calculates LCM(start, start+1, ..., end)
    if start > end:
        return 1
    return reduce(lcm, range(start, end + 1))

def calculate_x_k(k, n):
    # x_k = lcm(k, k+1, ..., k+n-1)
    end = k + n - 1
    return lcm_of_range(k, end)

# Test case parameters
N_values = [1, 2, 3, 4]
K_values_initial = [1, 2, 3, 4]
K_values_extended = [1, 2, 3, 4, 5, 6] # Extended range to check k > 4

results = {}

print("--- Detailed calculations for n=1, 2, 3, 4 ---")

for n in N_values:
    results[n] = {}
    print(f"\nTesting n = {n}")

    # 1. Calculate x_k and x_{k+1} for k=1, 2, 3, 4
    print("Initial check (k=1 to 4):")
    for k in K_values_initial:
        x_k = calculate_x_k(k, n)
        x_k_plus_1 = calculate_x_k(k + 1, n)

        is_increasing = x_k_plus_1 > x_k

        print(f"  k={k}: x_k = {x_k}, x_{k+1} = {x_k_plus_1}. Is x_{k+1} > x_k? {is_increasing}")

        if not is_increasing:
             # If it fails initially, it definitely won't be weakly increasing from the start.
             results[n][f"Initial_Fail_{k}"] = True

    # 2. Determine if x_{k+1} > x_k holds for k > 4 (Checking k=5, 6)
    print("\nExtended check (k=5, 6) to assess trend for k > 4:")
    extended_check_success = True

    for k in [5, 6]:
        if k not in K_values_initial: # Only check if not already checked
            x_k = calculate_x_k(k, n)
            x_k_plus_1 = calculate_x_k(k + 1, n)

            is_increasing = x_k_plus_1 > x_k

            print(f"  k={k}: x_k = {x_k}, x_{k+1} = {x_k_plus_1}. Is x_{k+1} > x_k? {is_increasing}")

            if not is_increasing:
                extended_check_success = False

    # 3. Conclusion for small n
    if all(results[n].get(f"Initial_Fail_{k}", False) == False for k in K_values_initial):
        # If the initial checks passed (or were not performed due to initial failure), 
        # we rely on the extended check for the conclusion asked by the prompt.
        if extended_check_success:
            results[n]["Conclusion"] = "Likely Solution (Based on checks)"
        else:
             results[n]["Conclusion"] = "Not a solution (Failed k=5 or k=6)"
    else:
        results[n]["Conclusion"] = "Not a solution (Failed initial checks)"


print("\n===================================")
print("Summary of results:")
for n, data in results.items():
    print(f"N={n}: Conclusion = {data['Conclusion']}")
print("===================================")
